}
function pick(list, rnd){ if(!list.length) return null; var r = rnd||Math.random; return list[Math.floor(r()*list.length)]; }
function shuffle(list, rnd){
  var r = rnd||Math.random; var a = list.slice();
  for(var i=a.length-1;i>0;i--){ var j=Math.floor(r()*(i+1)); var t=a[i]; a[i]=a[j]; a[j]=t; }
  return a;
}
function sample(list, k, rnd){
  if(k>=list.length) return shuffle(list, rnd);
  return shuffle(list, rnd).slice(0,k);
}
function weightedPick(items, weights, rnd){
  var r = rnd||Math.random; var sum=0; for(var i=0;i<weights.length;i++) sum+=weights[i];
